import{_ as t,o as a,c as o,a5 as d}from"./chunks/framework.BZzouRtU.js";const r="/study/images/browser/audio-crossfade-curves.svg",i="/study/images/browser/audio-crossfade-correlation.svg",p=JSON.parse('{"title":"Web Audioのクロスフェード — 等ゲイン・等電力・相関","description":"","frontmatter":{"title":"Web Audioのクロスフェード — 等ゲイン・等電力・相関","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"二つの音源を重ねて切り替え、ゲインの和を一定にする方法と、二乗和を一定にする方法を比較する。音源同士の相関によって中点のRMSが変わる仕組みを確かめる。","aliases":["Web Audio API","クロスフェード","crossfade","等ゲイン","等電力","equal gain","equal power","AudioParam","setValueCurveAtTime","RMS","相関"],"verification":"W3C Web Audio APIのAudioParamとDAFxのクロスフェード論文に照合（2026-11-06）"}},"headers":[],"relativePath":"browser/audio-crossfade.md","filePath":"browser/audio-crossfade.md"}'),s={name:"browser/audio-crossfade.md"};function c(n,e,l,u,h,g){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="web-audioのクロスフェード-—-等ゲイン・等電力・相関" tabindex="-1">Web Audioのクロスフェード — 等ゲイン・等電力・相関 <a class="header-anchor" href="#web-audioのクロスフェード-—-等ゲイン・等電力・相関" aria-label="Permalink to &quot;Web Audioのクロスフェード — 等ゲイン・等電力・相関&quot;">​</a></h1><p><strong>クロスフェード</strong>は、音源Aのゲインを下げながら音源Bのゲインを上げ、両方の出力を足して切り替える処理です。BGMの切り替えや、ゲームの環境音を入れ替える場面では、二つの音が重なる区間のレベルも考えます。前回のフェードで一つの音を小さくした処理と、ミキシングで複数の音を足した処理を組み合わせます。<a href="/study/browser/audio-gain-automation.html">Web Audioのゲインオートメーション</a>、<a href="/study/browser/audio-mixing-and-headroom.html">Web Audioのミキシング</a></p><h2 id="二つのゲイン曲線で切り替える" tabindex="-1">二つのゲイン曲線で切り替える <a class="header-anchor" href="#二つのゲイン曲線で切り替える" aria-label="Permalink to &quot;二つのゲイン曲線で切り替える&quot;">​</a></h2><p>切り替えの開始を <code>u = 0</code>、終了を <code>u = 1</code> とします。AとBの同じフレームの値を <code>a</code>、<code>b</code>、その時刻のゲインを <code>gA</code>、<code>gB</code> とすると、合成後の値は <code>y = gA × a + gB × b</code> です。Web Audioでは、二つの音源を別々の <code>GainNode</code> に通し、後段の同じ入力へつなぐと足し合わせられます。<a href="https://www.w3.org/TR/webaudio-1.1/#GainNode" target="_blank" rel="noreferrer">W3C Web Audio APIのGainNode</a>、<a href="https://www.w3.org/TR/webaudio-1.1/#channel-up-mixing-and-down-mixing" target="_blank" rel="noreferrer">チャンネルのミキシング</a></p><table tabindex="0"><thead><tr><th>方法</th><th>Aのゲイン</th><th>Bのゲイン</th><th>一定に保つ値</th><th style="text-align:right;">中点の各ゲイン</th></tr></thead><tbody><tr><td>等ゲイン（線形）</td><td><code>1 − u</code></td><td><code>u</code></td><td><code>gA + gB = 1</code></td><td style="text-align:right;"><code>0.50</code></td></tr><tr><td>等電力</td><td><code>cos(πu / 2)</code></td><td><code>sin(πu / 2)</code></td><td><code>gA² + gB² = 1</code></td><td style="text-align:right;">約 <code>0.707</code></td></tr></tbody></table><p>どちらも始点ではAだけが鳴り、終点ではBだけが鳴ります。中点では、等電力のほうが両方のゲインを高く保ちます。</p><figure class="study-figure"><img src="'+r+`" alt="進行度0から1までのゲインを比べる。等ゲインではAとBの直線が中点の0.50で交差する。等電力では余弦と正弦の曲線が中点の約0.707で交差する。どちらも開始時はAが1でBが0、終了時はAが0でBが1。" width="760" height="870" loading="lazy"><figcaption>線形ではゲインの和が1、等電力ではゲインの二乗和が1です。<a href="/study/images/browser/audio-crossfade-curves.svg" target="_blank" rel="noopener noreferrer">二つのゲイン曲線を拡大</a></figcaption></figure><h2 id="音源同士の相関で中点のレベルが変わる" tabindex="-1">音源同士の相関で中点のレベルが変わる <a class="header-anchor" href="#音源同士の相関で中点のレベルが変わる" aria-label="Permalink to &quot;音源同士の相関で中点のレベルが変わる&quot;">​</a></h2><p>ゲインを固定して短い区間を測るとき、入力の平均二乗値を <code>PA = mean(a²)</code>、<code>PB = mean(b²)</code> とします。合成後の平均二乗値 <code>Pout</code> には、AとBの同じフレームの値を掛け合わせた項も入ります。平均を除いた入力なら、<code>mean(a × b) = ρ × √(PA × PB)</code> と書けます。<code>ρ</code> は相関係数です。<a href="https://www.dafx.de/paper-archive/details/gUO-U6xEDk0Z_m4S-PivJQ" target="_blank" rel="noreferrer">Fink・Holters・Zölzerのクロスフェード論文</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pout = gA² × PA + gB² × PB + 2 × gA × gB × mean(a × b)</span></span>
<span class="line"><span>RMS  = √Pout</span></span></code></pre></div><p>同じ強さで相関が0の入力では、最後の項が0になります。そこで等電力の曲線を使うと、ゲインの二乗和が1なので、出力の平均二乗値は入力と同じになります。一方、同じ波形が同位相で重なると <code>a = b</code> になり、出力振幅は <code>gA + gB</code> 倍です。この場合は等ゲインで元の振幅を保ち、等電力では中点の振幅が <code>√2</code> 倍になります。複数の音が同じ向きに強く重なる区間では、ピークに余裕を持たせます。<a href="/study/browser/audio-mixing-and-headroom.html">Web Audioのミキシングとヘッドルーム</a></p><table tabindex="0"><thead><tr><th>同じ強さの入力</th><th style="text-align:right;">等ゲインの中点</th><th style="text-align:right;">等電力の中点</th></tr></thead><tbody><tr><td>400 Hzと600 Hzの波形を周期がそろう窓で測る</td><td style="text-align:right;">約 −3.01 dB</td><td style="text-align:right;">0 dB</td></tr><tr><td>同じ400 Hzの波形が同位相で重なる</td><td style="text-align:right;">0 dB</td><td style="text-align:right;">約 +3.01 dB</td></tr></tbody></table><p>ここでのdBは、片方だけが鳴っているときのRMSを基準にした <code>20 × log10(出力RMS / 基準RMS)</code> です。聞こえ方には周波数や再生環境も関わります。</p><figure class="study-figure"><img src="`+i+'" alt="入力の強さをそろえた理論値の比較。相関が0の場合、中点の等ゲインはマイナス3.01 dBで、等電力は0 dB。同じ波形が同位相で重なる場合、等ゲインは0 dBで、等電力はプラス3.01 dB。いずれも一方だけが鳴る始点と終点は0 dB。" width="760" height="870" loading="lazy"><figcaption>同じゲイン曲線でも、入力同士の重なり方で中点が下がる場合と上がる場合があります。<a href="/study/images/browser/audio-crossfade-correlation.svg" target="_blank" rel="noopener noreferrer">相関によるレベルの違いを拡大</a></figcaption></figure><h2 id="ブラウザで音の切り替えを測る" tabindex="-1">ブラウザで音の切り替えを測る <a class="header-anchor" href="#ブラウザで音の切り替えを測る" aria-label="Permalink to &quot;ブラウザで音の切り替えを測る&quot;">​</a></h2><p>実践では、48,000 Hzで1秒の音を用意します。ピーク振幅はどちらも <code>0.35</code> です。Aは400 Hzで、Bは600 HzまたはAと同じ波形です。200〜800 msでAからBへ切り替えます。ゲインの値を並べた配列を <code>AudioParam.setValueCurveAtTime()</code> に渡すと、ブラウザが指定区間で隣り合う値を線形に補間します。<a href="https://www.w3.org/TR/webaudio-1.1/#AudioParam" target="_blank" rel="noreferrer">W3C Web Audio APIのAudioParam</a>、<a href="https://www.w3.org/TR/webaudio-1.1/#OfflineAudioContext" target="_blank" rel="noreferrer">OfflineAudioContext</a></p><p>レンダリングした出力から、100 msを中心とする10 msのRMSを基準に、500 msを中心とする10 msのRMSを比べます。400 Hzと600 Hzはこの窓にそれぞれ4周期と6周期が収まるため、ゲインを固定した計算では二つの波形の積の平均が0になります。実践の窓内ではゲインも時間とともに動くので、表示する値は中点にゲインを固定した表の値に近い実測値です。<a href="/study/practice/browser/audio-crossfade-observation.html">クロスフェードの実践</a></p><p>同じ音を少し遅らせて重ねると、周波数ごとに足し合わさり方が変わります。<a href="/study/browser/audio-comb-filter.html">Web Audioのコムフィルター</a>で、遅延時間と打ち消しの関係を確認できます。</p>',18)])])}const f=t(s,[["render",c]]);export{p as __pageData,f as default};
